-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(255)  NOT NULL,
    grade    VARCHAR(1)    NOT NULL,
    rate     DECIMAL(9, 2) NOT NULL CHECK (rate >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A rate may carry a from-date: a grade may have several rates, one per from-date. A rate with no
-- from-date (null) applies from the beginning of time. At most one rate per grade and from-date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;

public class ApplyRate {
    public void apply(@Val Rate rate, Rates rates) {
        rates.save(rate);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditRateSet {
    public void audit(@Val Rate rate, ServerHttpConnection connection, Audit audit) {
        String[] fields = rate.from() == null
                ? new String[] { "grade=" + rate.grade(), "rate=" + rate.rate().toPlainString() }
                : new String[] { "grade=" + rate.grade(), "rate=" + rate.rate().toPlainString(), "from=" + rate.from() };
        audit.record(Audit.line("RATE_SET", rate.sheetId(), Audit.user(connection), fields));
    }
}
